 for(int i=0;i<18;i++){sample=new SystemSample{Utc=DateTime.UtcNow.AddSeconds(i*3),Cpu=55,MemoryUsed=8,MemoryTotal=16,Gpu=28,DiskBusy=14,Download=(Math.Sin(i*.6)+1.2)*1048576,Upload=(Math.Cos(i*.6)+1.2)*140000,NetworkName="测试网卡 · 界面验收数据"};card.Update(sample);}card.Update(sample);Check("repeated render does not duplicate history",((List<SystemSample>)Field(card,"history")).Count==18);Check("resource graph includes four metrics",((Dictionary<string,ProgressBar>)Field(card,"bars")).Count==4);Check("trend has two series",((Canvas)Field(card,"chart")).Children.Count==2);((TextBlock)Field(card,"exitText")).Text="203.0.113.5  （示例出口，非真实IP）\n示例国家 · 示例城市\nExample ISP";((TextBlock)Field(card,"exitState")).Text="出口与已确认记录一致 · 界面验收示例";Pump(120);Shot(card,Path.Combine(args[0],"notebook-card.png"));
