 var opaque=TaskbarAppearance.Preset("紧凑双行");opaque.Graphs=true;opaque.Transparent=false;opaque.AutoTheme=false;opaque.Background="#000000";opaque.GraphColor="#00AA00";opaque.LabelColor=opaque.ValueColor="#FFFFFF";config.Appearance=opaque;config.TaskbarItems=new List<string>{"cpu","memory","gpu","disk"};var geo=TaskbarPainter.Geometry(config,1,48);using(var b=TaskbarPainter.Preview(config,sample)){Check("usage color fills behind text within row",b.GetPixel((int)geo.Cells[0].X+1,(int)geo.Cells[0].Y+1).G>100);b.Save(Path.Combine(args[0],"taskbar-background-bars.png"));}int w1=geo.Size.Width;opaque.LabelGap+=10;Check("label value spacing changes width",TaskbarPainter.Geometry(config,1,48).Size.Width==w1+20);opaque.RowGap=5;var g2=TaskbarPainter.Geometry(config,1,48);Check("two row spacing is independently adjustable",Math.Abs(g2.Cells[1].Y-geo.Cells[1].Y-5)<.01);opaque.LabelGap=61;bool bad=false;try{opaque.Validate();}catch(ArgumentException){bad=true;}Check("invalid spacing rejected",bad);opaque.LabelGap=2;
 var exit=NetworkExit.Parse("{\"success\":true,\"ip\":\"203.0.113.5\",\"country\":\"Testland\",\"region\":\"Test\",\"connection\":{\"isp\":\"Test ISP\"}}");Check("exit parsed with provenance and time",exit.Ip=="203.0.113.5"&&exit.Isp=="Test ISP"&&exit.CheckedUtc>DateTime.UtcNow.AddMinutes(-1));Check("no VPN claim without baseline",exit.Status(config).Contains("尚未"));config.ExpectedExitIp=exit.Ip;config.ExpectedExitCountry=exit.Country;Check("confirmed exit matches baseline",exit.Status(config).Contains("一致"));exit.Ip="203.0.113.6";Check("node IP rotation is distinguished from outage",exit.Status(config).Contains("属地仍一致"));exit.Country="Elsewhere";Check("country drift requests VPN check",exit.Status(config).Contains("检查 VPN"));bad=false;try{NetworkExit.Parse("{\"success\":false}");}catch(InvalidDataException){bad=true;}Check("failed API response is not a healthy exit",bad);bad=false;try{NetworkExit.Parse("{\"success\":true,\"ip\":\"oops\",\"country\":\"X\"}");}catch(InvalidDataException){bad=true;}Check("invalid IP rejected",bad);
 var runtime=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);runtime.Config.Monitor.ExpectedExitIp=config.ExpectedExitIp;runtime.Config.Monitor.ExpectedExitCountry=config.ExpectedExitCountry;runtime.Save();runtime.Telemetry.Dispose();var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check("baseline persists in stable monitor configuration",restored.Config.Monitor.ExpectedExitIp==config.ExpectedExitIp&&restored.Config.Monitor.ExpectedExitCountry==config.ExpectedExitCountry);restored.Telemetry.Dispose();
 if(physicalInput){using(var outside=new OutsideTarget{Left=100,Top=100,Width=120,Height=90,StartPosition=System.Windows.Forms.FormStartPosition.Manual,ShowInTaskbar=false,TopMost=true}){outside.Show();Pump(100);card.Activate();Pump(100);var outsideCursor=System.Windows.Forms.Cursor.Position;SetCursorPos(outside.Left+40,outside.Top+50);Pump(80);var hit=System.Windows.Forms.Cursor.Position;if(WindowFromPoint(new NativePoint{X=hit.X,Y=hit.Y})!=outside.Handle)throw new Exception("Outside input target unavailable; no click sent");mouse_event(2,0,0,0,UIntPtr.Zero);Pump(200);mouse_event(4,0,0,0,UIntPtr.Zero);SetCursorPos(outsideCursor.X,outsideCursor.Y);Pump(100);Check("clicking non-activating outside surface dismisses card",!card.IsVisible);}}else{Console.WriteLine("SKIP physical click on non-activating surface: host pointer positioning unavailable");}card=new MonitorCard{Left=500,Top=100};card.Show();card.Activate();Pump(100);
 probe=new Window{Width=120,Height=90,Left=100,Top=100,Title="Conan isolated outside-click target"};probe.Show();probe.Activate();Pump(250);Check("activating outside window dismisses card",!card.IsVisible);Check("dismissal leaves taskbar readouts visible",IsWindowVisible(m.Handle)&&m.Visible);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(card!=null&&card.IsVisible)card.Close();if(probe!=null)probe.Close();m.Dispose();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"input-verification.json"),"{\"physical_pointer_verified\":"+(physicalInput?"true":"false")+",\"native_window_message_test\":true}");File.WriteAllText(Path.Combine(args[0],"interaction-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");Console.WriteLine("Checks "+checks+" Failures "+failures);return failures==0?0:1;}
